-- Initial Duke catalog supplied for the production database.
-- IDs are generated by PostgreSQL and relationships are resolved by stable slugs.
begin;

insert into public.schools(name,slug,email_domain,city,state,country,status)
values('Duke University','duke-university','duke.edu','Durham','North Carolina','United States','active')
on conflict(slug) do update set
 name=excluded.name,email_domain=excluded.email_domain,city=excluded.city,state=excluded.state,country=excluded.country,status=excluded.status;

insert into public.categories(school_id,name,slug,description,icon,status,sort_order)
select s.id,v.name,v.slug,v.description,v.icon,'active',v.sort_order
from public.schools s
cross join (values
 ('Dining','dining','Dining halls, cafes and individual food stations.','utensils',0),
 ('Housing','housing','Residential campuses, quads, houses and buildings.','home',1)
) as v(name,slug,description,icon,sort_order)
where s.slug='duke-university'
on conflict(school_id,slug) do update set
 name=excluded.name,description=excluded.description,icon=excluded.icon,status=excluded.status,sort_order=excluded.sort_order;

insert into public.rating_dimensions(category_id,key,label,description,min_value,max_value,sort_order,is_required,is_active)
select c.id,v.key,v.label,v.description,1,5,v.sort_order,true,true
from public.categories c
join public.schools s on s.id=c.school_id and s.slug='duke-university'
join (values
 ('dining','taste','Taste','Quality and consistency of the food.',0),
 ('dining','value','Meal Plan Value','Value relative to price or meal-plan cost.',1),
 ('dining','wait-time','Wait time','How manageable the wait usually is.',2),
 ('housing','comfort','Comfort','Day-to-day comfort of the residence.',0),
 ('housing','location','Location','Convenience of the campus location.',1),
 ('housing','facilities','Facilities','Quality and usefulness of shared facilities.',2)
) as v(category_slug,key,label,description,sort_order) on v.category_slug=c.slug
on conflict(category_id,key) do update set
 label=excluded.label,description=excluded.description,sort_order=excluded.sort_order,is_required=excluded.is_required,is_active=excluded.is_active;

create temporary table seed_duke_entities(
 name text not null,
 slug text primary key,
 category_slug text not null,
 parent_slug text,
 location_name text not null,
 depth integer not null,
 is_featured boolean not null default false
) on commit drop;

