do $$
declare current_depth integer;
begin
 for current_depth in 0..2 loop
  insert into public.entities(
   school_id,category_id,parent_entity_id,name,slug,short_description,description,location_name,
   address,official_url,source_name,source_url,metadata,status,is_featured
  )
  select s.id,c.id,p.id,se.name,se.slug,
   case when se.category_slug='dining' then 'A Duke dining location.' else 'A Duke housing location.' end,
   case when se.category_slug='dining' then 'A dining location in the Duke campus catalog.' else 'A residential location in the Duke campus catalog.' end,
   se.location_name,'','','','', '{}'::jsonb,'active',se.is_featured
  from seed_duke_entities se
  join public.schools s on s.slug='duke-university'
  join public.categories c on c.school_id=s.id and c.slug=se.category_slug
  left join public.entities p on p.slug=se.parent_slug
  where se.depth=current_depth and (se.parent_slug is null or p.id is not null)
  on conflict(slug) do nothing;
 end loop;

 if exists(
  select 1 from seed_duke_entities se
  left join public.entities e on e.slug=se.slug
  left join public.entities p on p.id=e.parent_entity_id
  left join public.categories c on c.id=e.category_id
  left join public.schools s on s.id=e.school_id
  where e.id is null or s.slug<>'duke-university' or c.slug<>se.category_slug
   or (se.parent_slug is null and e.parent_entity_id is not null)
   or (se.parent_slug is not null and p.slug is distinct from se.parent_slug)
 ) then
  raise exception 'The Duke catalog could not be imported without a slug or hierarchy conflict.';
 end if;
end $$;

commit;
